import java.util.List;
import java.util.Map;
import java.util.Set;

public class ImmutableDemo {
    public static void main(String[] args) {
        // Creating immutable lists, sets, and maps safely
        List<String> roles = List.of("ADMIN", "USER", "GUEST");
        Set<String> permissions = Set.of("READ", "WRITE");
        Map<String, Integer> metrics = Map.of(
            "cpu", 42,
            "memory", 85
        );

        // The following lines compile successfully but throw exceptions at runtime:
        // roles.add("SUPERVISOR"); // UnsupportedOperationException
        // Map.of("key", null);    // NullPointerException
        // Set.of("A", "A");         // IllegalArgumentException
    }
}
